5	#include "torch_kernel_helper.h"
6	#include "tiling/platform/platform_ascendc.h"
7	#include "aclrtlaunch_less_kernel.h"
8	
9	#include <algorithm>
10	
11	namespace ascend_kernel {
12	
13	constexpr int64_t CACHE_LINE_BYTE = 512;
14	constexpr int64_t COMPARE_ALIGN = 64;
15	
16	static int64_t getBufferCoefficient(int64_t dtypeSize)
17	{
18	    // UB: 2*inQ*dtypeSize*2 + outQ*4 + tempBuf*20 (5 float slots * 4)
19	    if (dtypeSize == 2) return 32;   // 4+4+4+20 = 32
20	    if (dtypeSize == 4) return 40;   // 8+8+4+20 = 40
21	    if (dtypeSize == 8) return 56;   // 16+16+4+20 = 56
22	    return 40;
23	}
24	
25	at::Tensor less(const at::Tensor &x1, const at::Tensor &x2)
26	{
27	    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
28	                "less: inputs must have same dtype");
29	
30	    auto dtype = x1.scalar_type();
31	    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat ||
32	                dtype == at::kInt || dtype == at::kLong || dtype == at::kChar || dtype == at::kByte,
33	                "less: unsupported dtype ", dtype);
34	
35	    auto shape = at::infer_size(x1.sizes(), x2.sizes());
36	    int64_t totalLength = 1;
37	    for (auto d : shape) { totalLength *= d; }
38	
39	    if (totalLength == 0) {
40	        return at::empty(shape, x1.options().dtype(at::kHalf)).to(at::kBool);
41	    }
42	
43	    // For tiny tensors (< 64 elements), fall back to PyTorch
44	    // AscendC Compare API requires >= 64 elements (256B alignment)
45	    if (totalLength < COMPARE_ALIGN) {
46	        return at::less(x1, x2);
47	    }
48	
49	    // --- Prepare inputs ---
50	    at::Tensor x1_bc = x1;
51	    at::Tensor x2_bc = x2;
52	    if (x1.sizes() != shape) { x1_bc = x1.expand(shape); }
53	    if (x2.sizes() != shape) { x2_bc = x2.expand(shape); }
54	
55	    int64_t effectiveDtypeSize = x1.element_size();
56	
57	    // int8/uint8 → float32 (AscendC Cast doesn't support int8)
58	    if (dtype == at::kChar || dtype == at::kByte) {
59	        x1_bc = x1_bc.to(at::kFloat).contiguous();
60	        x2_bc = x2_bc.to(at::kFloat).contiguous();
61	        effectiveDtypeSize = 4;
62	    } else {
63	        x1_bc = x1_bc.contiguous();
64	        x2_bc = x2_bc.contiguous();
65	    }
66	
67	    int64_t isInteger = 0;
68	    if (effectiveDtypeSize == 4 && dtype == at::kInt) { isInteger = 1; }
69	    if (effectiveDtypeSize == 8) { isInteger = 1; }
70	
71	    auto output = at::empty(shape, x1.options().dtype(at::kHalf));
72	
73	    // --- Hardware params ---
74	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
75	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
76	    uint64_t ubSize;
77	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
78	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
79	
80	    // --- Block-level tiling (Cache Line in bytes) ---
81	    int64_t clAlign = std::max(CACHE_LINE_BYTE / effectiveDtypeSize, static_cast<int64_t>(1));
82	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
83	    int64_t totalLengthCoreAlign = (totalLengthCore + clAlign - 1) / clAlign * clAlign;
84	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
85	    int64_t formerNum = usedCoreNum - 1;
86	    int64_t formerLength = totalLengthCoreAlign;
87	    int64_t tailLength = totalLength - formerNum * formerLength;
88	
89	    // --- UB-level tiling ---
90	    int64_t bufferCoefficient = getBufferCoefficient(effectiveDtypeSize);
91	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
92	    if (effectiveDtypeSize == 0) { effectiveDtypeSize = 1; }
93	    int64_t alignElements = std::max(32 / effectiveDtypeSize, COMPARE_ALIGN);
94	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
95	
96	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
97	
98	    EXEC_KERNEL_CMD(less_kernel, blockDim,
99	                    x1_bc, x2_bc, output,
100	                    formerNum, formerLength, tailLength, tileLength,
101	                    effectiveDtypeSize, isInteger);
102	
103	    return output.to(at::kBool);
104	}
105	
106	}  // namespace ascend_kernel
