11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelLess {
17	public:
18	    __aicore__ inline KernelLess() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength,
23	                                int64_t dtypeSize)
24	    {
25	        int64_t blockIdx = AscendC::GetBlockIdx();
26	
27	        if (blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = formerLength * blockIdx;
30	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
31	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
32	            zGm.SetGlobalBuffer((__gm__ half *)z + offset, formerLength);
33	        } else {
34	            this->blockLength = tailLength;
35	            int64_t offset = formerLength * formerNum;
36	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
37	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
38	            zGm.SetGlobalBuffer((__gm__ half *)z + offset, tailLength);
39	        }
40	
41	        this->tileLength = tileLength;
42	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
43	        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
44	        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(half));
45	
46	        // Temp buffer layout (all types):
47	        // [mask(0)] [buf1(1)] [buf2(2)] [buf3(3)] [buf4(4)] = 5 float slots
48	        this->tempSlots = 5;
49	        pipe.InitBuffer(tempBuf, this->tempSlots * tileLength * sizeof(float));
50	    }
51	
52	    __aicore__ inline void Process()
53	    {
54	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
55	        if (tileNum == 0) { return; }
56	
57	        int64_t tailLen = this->blockLength - (tileNum - 1) * this->tileLength;
58	        constexpr int64_t kCompareAlign = 64;
59	        int64_t tailAligned = ((tailLen + kCompareAlign - 1) / kCompareAlign) * kCompareAlign;
60	
61	        for (int64_t i = 0; i < tileNum - 1; ++i) {
62	            CopyIn(i, this->tileLength);
63	            Compute(i, this->tileLength);
64	            CopyOut(i, this->tileLength);
65	        }
66	        // Tail: use aligned length for CopyIn (ensures Compare alignment)
67	        CopyIn(tileNum - 1, tailAligned);
68	        Compute(tileNum - 1, tailAligned);
69	        CopyOut(tileNum - 1, tailLen);
70	    }
71	
72	private:
73	    __aicore__ inline void CopyIn(int64_t progress, int64_t curLen)
74	    {
75	        auto xLocal = inQueueX.AllocTensor<T>();
76	        auto yLocal = inQueueY.AllocTensor<T>();
77	        AscendC::DataCopyExtParams p{1, static_cast<uint32_t>(curLen * sizeof(T)), 0, 0, 0};
78	        AscendC::DataCopyPadExtParams<T> pad{false, 0, 0, 0};
79	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], p, pad);
80	        AscendC::DataCopyPad(yLocal, yGm[progress * this->tileLength], p, pad);
81	        inQueueX.EnQue(xLocal);
82	        inQueueY.EnQue(yLocal);
83	    }
84	
85	    __aicore__ inline void Compute(int64_t progress, int64_t curLen)
86	    {
87	        auto xLocal = inQueueX.DeQue<T>();
88	        auto yLocal = inQueueY.DeQue<T>();
89	        auto zLocal = outQueueZ.AllocTensor<half>();
90	        int64_t tl = this->tileLength;
91	        auto temp = tempBuf.Get<float>();
92	        auto mask = temp.ReinterpretCast<uint8_t>();
93	
94	        if constexpr (std::is_same_v<T, float>) {
95	            auto oneFp32 = temp[3 * tl];
96	            auto dstFp32 = temp[4 * tl];
97	            AscendC::Duplicate(oneFp32, 1.0f, curLen);
98	            AscendC::Compare(mask, xLocal, yLocal, AscendC::CMPMODE::LT, curLen);
99	            AscendC::Select(dstFp32, mask, oneFp32, 0.0f,
100	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curLen);
101	            AscendC::Cast(zLocal, dstFp32, AscendC::RoundMode::CAST_ROUND, curLen);
102	
103	        } else if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
104	            auto castX = temp[tl];
105	            auto castY = temp[2 * tl];
106	            auto oneFp32 = temp[3 * tl];
107	            auto dstFp32 = temp[4 * tl];
108	            AscendC::Cast(castX, xLocal, AscendC::RoundMode::CAST_NONE, curLen);
109	            AscendC::Cast(castY, yLocal, AscendC::RoundMode::CAST_NONE, curLen);
110	            AscendC::Duplicate(oneFp32, 1.0f, curLen);
111	            AscendC::Compare(mask, castX, castY, AscendC::CMPMODE::LT, curLen);
112	            AscendC::Select(dstFp32, mask, oneFp32, 0.0f,
113	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curLen);
114	            AscendC::Cast(zLocal, dstFp32, AscendC::RoundMode::CAST_ROUND, curLen);
115	
116	        } else if constexpr (std::is_same_v<T, int32_t>) {
117	            // int32: Compare in int32 domain, Select in half
118	            auto halfBuf = temp[tl].ReinterpretCast<half>();
119	            auto oneHalf = halfBuf;
120	            auto dstHalf = halfBuf[tl];
121	            AscendC::Compare(mask, xLocal, yLocal, AscendC::CMPMODE::LT, curLen);
122	            AscendC::Duplicate(oneHalf, static_cast<half>(1.0f), curLen);
123	            AscendC::Select(dstHalf, mask, oneHalf, static_cast<half>(0.0f),
124	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curLen);
125	            AscendC::DataCopy(zLocal, dstHalf, curLen);
126	
127	        } else {
128	            // int64: Cast to float
129	            auto castX = temp[tl];
130	            auto castY = temp[2 * tl];
131	            auto oneFp32 = temp[3 * tl];
132	            auto dstFp32 = temp[4 * tl];
133	            AscendC::Cast(castX, xLocal, AscendC::RoundMode::CAST_NONE, curLen);
134	            AscendC::Cast(castY, yLocal, AscendC::RoundMode::CAST_NONE, curLen);
135	            AscendC::Duplicate(oneFp32, 1.0f, curLen);
136	            AscendC::Compare(mask, castX, castY, AscendC::CMPMODE::LT, curLen);
137	            AscendC::Select(dstFp32, mask, oneFp32, 0.0f,
138	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curLen);
139	            AscendC::Cast(zLocal, dstFp32, AscendC::RoundMode::CAST_ROUND, curLen);
140	        }
141	
142	        outQueueZ.EnQue(zLocal);
143	        inQueueX.FreeTensor(xLocal);
144	        inQueueY.FreeTensor(yLocal);
145	    }
146	
147	    // Tail tile: curLen actual elements, paddedLen >= 64 for Compare alignment
148	    __aicore__ inline void ComputePad(int64_t progress, int64_t curLen, int64_t padLen)
149	    {
150	        auto xLocal = inQueueX.DeQue<T>();
151	        auto yLocal = inQueueY.DeQue<T>();
152	        auto zLocal = outQueueZ.AllocTensor<half>();
153	        int64_t tl = this->tileLength;
154	        auto temp = tempBuf.Get<float>();
155	        auto mask = temp.ReinterpretCast<uint8_t>();
156	
157	        if constexpr (std::is_same_v<T, float>) {
158	            auto oneFp32 = temp[3 * tl];
159	            auto dstFp32 = temp[4 * tl];
160	            AscendC::Duplicate(oneFp32, 1.0f, padLen);
161	            AscendC::Compare(mask, xLocal, yLocal, AscendC::CMPMODE::LT, padLen);
162	            AscendC::Select(dstFp32, mask, oneFp32, 0.0f,
163	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, padLen);
164	            AscendC::Cast(zLocal, dstFp32, AscendC::RoundMode::CAST_ROUND, curLen);
165	
166	        } else if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
167	            auto castX = temp[tl];
168	            auto castY = temp[2 * tl];
169	            auto oneFp32 = temp[3 * tl];
170	            auto dstFp32 = temp[4 * tl];
171	            AscendC::Cast(castX, xLocal, AscendC::RoundMode::CAST_NONE, curLen);
172	            AscendC::Cast(castY, yLocal, AscendC::RoundMode::CAST_NONE, curLen);
173	            AscendC::Duplicate(castX[curLen], 0.0f, padLen - curLen);
174	            AscendC::Duplicate(castY[curLen], 0.0f, padLen - curLen);
175	            AscendC::Duplicate(oneFp32, 1.0f, padLen);
176	            AscendC::Compare(mask, castX, castY, AscendC::CMPMODE::LT, padLen);
177	            AscendC::Select(dstFp32, mask, oneFp32, 0.0f,
178	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, padLen);
179	            AscendC::Cast(zLocal, dstFp32, AscendC::RoundMode::CAST_ROUND, curLen);
180	
181	        } else if constexpr (std::is_same_v<T, int32_t>) {
182	            // int32: pad in int32 domain, then Compare+Select in half
183	            auto halfBuf = temp[tl].ReinterpretCast<half>();
184	            auto oneHalf = halfBuf;
185	            auto dstHalf = halfBuf[tl];
186	            AscendC::Duplicate(xLocal[curLen], 0, padLen - curLen);
187	            AscendC::Duplicate(yLocal[curLen], 0, padLen - curLen);
188	            AscendC::Compare(mask, xLocal, yLocal, AscendC::CMPMODE::LT, padLen);
189	            AscendC::Duplicate(oneHalf, static_cast<half>(1.0f), padLen);
190	            AscendC::Select(dstHalf, mask, oneHalf, static_cast<half>(0.0f),
191	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, padLen);
192	            AscendC::DataCopy(zLocal, dstHalf, curLen);
193	
194	        } else {
195	            // int64: Cast to float, pad, Compare
196	            auto castX = temp[tl];
197	            auto castY = temp[2 * tl];
198	            auto oneFp32 = temp[3 * tl];
199	            auto dstFp32 = temp[4 * tl];
200	            AscendC::Cast(castX, xLocal, AscendC::RoundMode::CAST_NONE, curLen);
201	            AscendC::Cast(castY, yLocal, AscendC::RoundMode::CAST_NONE, curLen);
202	            AscendC::Duplicate(castX[curLen], 0.0f, padLen - curLen);
203	            AscendC::Duplicate(castY[curLen], 0.0f, padLen - curLen);
204	            AscendC::Duplicate(oneFp32, 1.0f, padLen);
205	            AscendC::Compare(mask, castX, castY, AscendC::CMPMODE::LT, padLen);
206	            AscendC::Select(dstFp32, mask, oneFp32, 0.0f,
207	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, padLen);
208	            AscendC::Cast(zLocal, dstFp32, AscendC::RoundMode::CAST_ROUND, curLen);
209	        }
210	
211	        outQueueZ.EnQue(zLocal);
212	        inQueueX.FreeTensor(xLocal);
213	        inQueueY.FreeTensor(yLocal);
214	    }
215	
216	    __aicore__ inline void CopyOut(int64_t progress, int64_t curLen)
217	    {
218	        auto zLocal = outQueueZ.DeQue<half>();
219	        AscendC::DataCopy(zGm[progress * this->tileLength], zLocal, curLen);
220	        outQueueZ.FreeTensor(zLocal);
221	    }
222	
223	private:
224	    AscendC::TPipe pipe;
225	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
226	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
227	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
228	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf;
229	    AscendC::GlobalTensor<T> xGm;
230	    AscendC::GlobalTensor<T> yGm;
231	    AscendC::GlobalTensor<half> zGm;
232	    int64_t blockLength;
233	    int64_t tileLength;
234	    int64_t tempSlots;
235	};
236	
237	extern "C" __global__ __aicore__ void less_kernel(GM_ADDR x, GM_ADDR y, GM_ADDR z,
238	                                                   int64_t formerNum, int64_t formerLength,
239	                                                   int64_t tailLength, int64_t tileLength,
240	                                                   int64_t dtypeSize, int64_t isInteger)
241	{
242	    // int8/uint8 are converted to float32 in host; dtypeSize==1 never reaches here
243	    if (dtypeSize == 2) {
244	        KernelLess<half> op;
245	        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, dtypeSize);
246	        op.Process();
247	    } else if (dtypeSize == 4) {
248	        if (isInteger) {
249	            KernelLess<int32_t> op;
250	            op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, dtypeSize);
251	            op.Process();
252	        } else {
253	            KernelLess<float> op;
254	            op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, dtypeSize);
255	            op.Process();
256	        }
257	    } else {
258	        KernelLess<int64_t> op;
259	        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, dtypeSize);
260	        op.Process();
261	    }
262	}
