#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_less_kernel.h"

#include <algorithm>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE = 512;
constexpr int64_t COMPARE_ALIGN = 64;

static int64_t getBufferCoefficient(int64_t dtypeSize)
{
    // UB: 2*inQ*dtypeSize*2 + outQ*4 + tempBuf*20 (5 float slots * 4)
    if (dtypeSize == 2) return 32;   // 4+4+4+20 = 32
    if (dtypeSize == 4) return 40;   // 8+8+4+20 = 40
    if (dtypeSize == 8) return 56;   // 16+16+4+20 = 56
    return 40;
}

at::Tensor less(const at::Tensor &x1, const at::Tensor &x2)
{
    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
                "less: inputs must have same dtype");

    auto dtype = x1.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat ||
                dtype == at::kInt || dtype == at::kLong || dtype == at::kChar || dtype == at::kByte,
                "less: unsupported dtype ", dtype);

    auto shape = at::infer_size(x1.sizes(), x2.sizes());
    int64_t totalLength = 1;
    for (auto d : shape) { totalLength *= d; }

    if (totalLength == 0) {
        return at::empty(shape, x1.options().dtype(at::kHalf)).to(at::kBool);
    }

    // For tiny tensors (< 64 elements), fall back to PyTorch
    if (totalLength < COMPARE_ALIGN) {
        return at::less(x1, x2);
    }

    // AscendC Compare CMPMODE::LT is NOT supported for int32/int64 on Atlas A2/A3.
    // Fall back to PyTorch for integer types.
    if (dtype == at::kInt || dtype == at::kLong) {
        return at::less(x1, x2);
    }

    // --- Prepare inputs ---
    at::Tensor x1_bc = x1;
    at::Tensor x2_bc = x2;
    if (x1.sizes() != shape) { x1_bc = x1.expand(shape); }
    if (x2.sizes() != shape) { x2_bc = x2.expand(shape); }

    int64_t effectiveDtypeSize = x1.element_size();

    // int8/uint8 → float32 (AscendC Cast doesn't support int8)
    if (dtype == at::kChar || dtype == at::kByte) {
        x1_bc = x1_bc.to(at::kFloat).contiguous();
        x2_bc = x2_bc.to(at::kFloat).contiguous();
        effectiveDtypeSize = 4;
    } else {
        x1_bc = x1_bc.contiguous();
        x2_bc = x2_bc.contiguous();
    }

    // isInteger is kept for kernel signature compatibility but always 0 now
    // since int32/int64 fallback happens above
    int64_t isInteger = 0;

    auto output = at::empty(shape, x1.options().dtype(at::kHalf));

    // --- Hardware params ---
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // --- Block-level tiling (Cache Line in bytes) ---
    int64_t clAlign = std::max(CACHE_LINE_BYTE / effectiveDtypeSize, static_cast<int64_t>(1));
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + clAlign - 1) / clAlign * clAlign;
    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // --- UB-level tiling ---
    int64_t bufferCoefficient = getBufferCoefficient(effectiveDtypeSize);
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (effectiveDtypeSize == 0) { effectiveDtypeSize = 1; }
    int64_t alignElements = std::max(32 / effectiveDtypeSize, COMPARE_ALIGN);
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(less_kernel, blockDim,
                    x1_bc, x2_bc, output,
                    formerNum, formerLength, tailLength, tileLength,
                    effectiveDtypeSize, isInteger);

    return output.to(at::kBool);
}

}  // namespace ascend_kernel
