        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, dtypeSize);
        op.Process();
    } else {
        // dtypeSize == 8 or others (int64 was handled by host fallback)
        KernelLess<int64_t> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, dtypeSize);
        op.Process();
    }
